package com.sentinelai.automation.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="playbook_approval") public class PlaybookApproval { @Id private UUID id; private UUID executionId; private String tenantId; private String reviewer; private String decision; private String reason; private Instant createdAt; protected PlaybookApproval(){} public PlaybookApproval(UUID id,UUID execution,String tenant,String reviewer,String decision,String reason){this.id=id;executionId=execution;tenantId=tenant;this.reviewer=reviewer;this.decision=decision;this.reason=reason;createdAt=Instant.now();} public UUID getId(){return id;} public UUID getExecutionId(){return executionId;} public String getTenantId(){return tenantId;} public String getReviewer(){return reviewer;} public String getDecision(){return decision;} public String getReason(){return reason;} public Instant getCreatedAt(){return createdAt;} }
